sysauto_script.script:
var reqGr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
reqGr.addQuery('state', 'Submitted');
reqGr.addQuery('customer_type', 'Trade');
reqGr.query();

while (reqGr.next()) {

    var segment = reqGr.getValue('segment');
    var initiator = reqGr.getValue('initiator');

    var firstApprover = '';

    switch (segment) {
        case 'Cement':
            firstApprover = reqGr.getValue('u_approver_tsh');
            break;

        case 'RMC':
            firstApprover = reqGr.getValue('u_approver_tsm');
            break;

        case 'BPD':
            firstApprover = reqGr.getValue('u_approver_tsh_bpd');
            break;
    }

    // Auto approve only if Initiator = TSH/TSM/TSH_BPD
    if (!firstApprover || firstApprover != initiator)
        continue;

    var appr = new GlideRecord('sysapproval_approver');
    appr.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
    appr.addQuery('document_id', reqGr.getUniqueValue());
    appr.addQuery('approver', firstApprover);
    appr.addQuery('state', 'requested');
    appr.query();

    if (appr.next()) {

        appr.setValue('state', 'approved');
        appr.setValue(
            'comments',
            'Auto Approved - Initiator and First Approver are the same user'
        );

        appr.setWorkflow(false);
        appr.update();

        gs.info(
            'CLM AutoApprove Scheduler: Auto approved first approval for request ' +
            reqGr.getValue('request_number')
        );
    }
}
